      if(p.status==='registered')return `<p class="fine-print"><strong>Proof ${i+1} · REGISTERED · TokenExists</strong> — policy <span class="mono">${esc(p.policy)}</span> is registry node ${p.nodeIndex} in this list: include that node as a reference input, and the token's transfer logic must run in the transaction.</p>`;
      if(p.status==='unregistered')return `<p class="fine-print"><strong>Proof ${i+1} · NOT REGISTERED · TokenDoesNotExist</strong> — covering node ${p.nodeIndex}, key <span class="mono">${esc(p.nodeKey)}</span>, whose next is <span class="mono">${esc(p.nextKey)}</span>: ${esc(p.nodeKey)} &lt; ${esc(p.policy)} &lt; ${esc(p.nextKey)}, so the policy is proved absent and the asset is treated as an ordinary native token that can always leave the base script.</p>`;
