  if(el.dataset.design){let value=el.type==='checkbox'?el.checked:el.value;if(el.dataset.design==='decimals')value=Number(value);if(el.dataset.design==='ticker'){value=value.toUpperCase();el.value=value;}state.design[el.dataset.design]=value;state.simulation=null;state.seqResult=null;state.supplyResult=null;state.supplySeqResult=null;state.timelineResult=null;if(el.dataset.design==='substandard'){state.subPreset=null;state.subResult=null;state.subMode='preset';state.subCustom=null;state.seizureResult=null;state.seizureMode='preset';state.seizureCustom=null;state.denylistResult=null;state.kycSeqResult=null;state.basicKycResult=null;}save();renderPreview();}
  if(el.dataset.credit){state.credit[el.dataset.credit]=el.value===''?NaN:Number(el.value);updateCredit();}
